/**
 * Uzbek Wordle (So'ztop) - So'zlar lug'ati
 * O'zbek tilining izohli lug'ati (Izoh.uz / Hunspell) asosida shakllantirilgan
 */

// O'zbek lotin harflari va o' / g' ni to'g'ri ajratish yordamchisi
function splitUzbekTokens(str) {
  if (!str) return [];
  const normalized = str.toLowerCase()
    .replace(/[\u02BB\u02BC\u2018\u2019\u0060\u0027\u00B4]/g, "'");
  const tokens = [];
  let i = 0;
  while (i < normalized.length) {
    if (i + 1 < normalized.length && (normalized.substr(i, 2) === "o'" || normalized.substr(i, 2) === "g'")) {
      tokens.push(normalized.substr(i, 2));
      i += 2;
    } else {
      tokens.push(normalized[i]);
      i += 1;
    }
  }
  return tokens;
}

// Izoh.uz dan so'z ma'nosini onlayn tekshirish (fallback kesh bilan)
const IZOH_CACHE = new Set();
async function checkIzohWordOnline(word) {
  const clean = word.toLowerCase().trim();
  if (IZOH_CACHE.has(clean)) return true;
  try {
    const encoded = encodeURIComponent(clean);
    // Bepul va tezkor CORS proxy orqali Izoh.uz dan tekshirish
    const proxyUrl = `https://api.allorigins.win/raw?url=${encodeURIComponent('https://izoh.uz/word/' + encoded)}`;
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 2500);
    const resp = await fetch(proxyUrl, { signal: controller.signal });
    clearTimeout(timeoutId);
    if (resp.ok) {
      const html = await resp.text();
      // Agar sahifada so'z mavjud bo'lsa
      if (html && !html.includes('410 Gone') && !html.includes('topilmadi')) {
        IZOH_CACHE.add(clean);
        return true;
      }
    }
  } catch (e) {
    // Tarmoq xatosi bo'lsa mahalliy tekshiruvga tayanish
  }
  return false;
}

